-- ROLLBACK of 27: removes only the draft set versions created by 27 (marked ${MARK}); no attempts can reference a draft. Published sets untouched.
-- generated by scripts/prod-open/sat-order-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched; items unchanged, only positions rearranged inside each module.

do $rb27$ declare v_n int; begin
  delete from mock_exam_sets s where s.status = 'draft' and s.readiness_report->>'officialOrder27' = 'true' and s.name ~ '^SAT Practice Test [0-9]+$'
    and not exists (select 1 from mock_exam_attempts a where a.exam_set_id = s.id)
    and exists (select 1 from mock_exam_sets p where p.set_group_id = s.set_group_id and p.status = 'published' and p.version_no < s.version_no);
  get diagnostics v_n = row_count; raise notice 'draft set versions removed: %', v_n;
end $rb27$;
